def output_path() -> Path:
    """Return the destination path, honouring MAKEFUN_OUTPUT_DIR."""
    override = os.environ.get("MAKEFUN_OUTPUT_DIR")
    directory = Path(override) if override else DEFAULT_OUTPUT_DIR
    return directory / OUTPUT_NAME


def main() -> Path:
    """Decode the embedded image and write it to the output path."""
    data = base64.b64decode(ENTRY_PNG_B64)
    target = output_path()
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(data)
    return target


if __name__ == "__main__":
    print(main())
